; SLAM II Single-Server Quality Inspection Station
GEN, PRITSKER, INSPECTION_STATION, 1/1/1979, 1;
LIMITS, 1, 2, 100;
INITIALIZE, 0.0, 480.0;
NETWORK;
  CREATE, EXPON(6.0), 0.0, 1;
  QINSP QUEUE(1), 0, 50;
        ACTIVITY/1, UNFRM(3.5, 5.5);
        COLCT, INT(1), TIME_IN_INSPECTION;
        TERMINATE;
ENDNETWORK;
FIN;

; SLAM II Two-Stage Serial Assembly Line with Finite Inter-Stage Buffer
GEN, ANALYST, SERIAL_ASSEMBLY, 1/1/1979, 1;
LIMITS, 2, 2, 150;
INITIALIZE, 0.0, 480.0;
NETWORK;
  CREATE, EXPON(4.0), 0.0, 1;
  STG1  QUEUE(1), 0, 40;
        ACTIVITY/1, RNORM(3.2, 0.4), 1.0, STG2;
  STG2  QUEUE(2), 0, 10;
        ACTIVITY/2, RNORM(3.5, 0.5), 1.0, EXIT1;
  EXIT1 COLCT, INT(1), TOTAL_FLOW_TIME;
        TERMINATE;
ENDNETWORK;
FIN;

; SLAM II Multi-Resource CNC Machining Cell with Shared Setup Operator
GEN, PRITSKER, CNC_MACHINING_CELL, 1/1/1979, 1;
LIMITS, 3, 3, 200;
INITIALIZE, 0.0, 600.0;
NETWORK;
  RESOURCE/CNC(3), 1;
  RESOURCE/OPERATOR(1), 2;
  CREATE, EXPON(5.0), 0.0, 1;
  WCNC  AWAIT(1), CNC/1;
  WOP1  AWAIT(2), OPERATOR/1;
        ACTIVITY/1, UNFRM(1.5, 2.5), 1.0, RELOP;
  RELOP FREE, OPERATOR/1;
        ACTIVITY/2, RNORM(11.0, 1.5), 1.0, RELCNC;
  RELCNC FREE, CNC/1;
        COLCT, INT(1), PART_CYCLE_TIME;
        TERMINATE;
ENDNETWORK;
FIN;

; Pritsker Combined Discrete-Continuous Tanker Unloading Terminal
GEN, PRITSKER, TANKER_TERMINAL, 1/1/1979, 1;
LIMITS, 4, 3, 150;
CONTINUOUS, 2, 1, 0.01, 0.1, 0.1;
INTLC, SS(1)=100.0, SS(2)=500.0, XX(1)=0.0, XX(2)=1.0;
INITIALIZE, 0.0, 30.0;

; Continuous crude-oil unloading and refinery consumption ODEs
DD(1) = 300.0 * XX(1) - 150.0 * XX(2);
DD(2) = 150.0 * XX(2) - 120.0;
SS(3) = SS(1) + SS(2);

NETWORK;
  RESOURCE/BERTH(1), 1;
  GATE/PORT, OPEN, 2;
  CREATE, EXPON(4.0), 0.0, 1, 20, 1;
  ARR   AWAIT(1), BERTH/1, , 1;
        ASSIGN, XX(1)=1.0, 1;
        ACTIVITY/1, 1.5, 1.0, DONE;
  DONE  FREE, BERTH/1, 1;
        CLOSE, PORT, 1;
        OPEN, PORT, 1;
        COLCT, INT(1), TANKER_TURNAROUND, 1;
        TERMINATE, 20;
  DET1  DETECT, SS(1), XP, 350.0, 0.01, 1;
        ASSIGN, XX(1)=0.0, 1;
        TERMINATE;
ENDNETWORK;
FIN;

; SLAM II Automated Automotive Paint-Bake-Inspect Line with Rework & Oven Thermal Model
GEN, PRITSKER, AUTOMOTIVE_PAINT_LINE, 1/1/1979, 1;
LIMITS, 5, 4, 250;
CONTINUOUS, 1, 0, 0.05, 0.5, 0.5;
INTLC, SS(1)=160.0, XX(1)=1.0;
INITIALIZE, 0.0, 480.0;

; Curing oven temperature control dynamics (C)
DD(1) = 0.08 * (180.0 * XX(1) - SS(1));

NETWORK;
  RESOURCE/BOOTH(2), 1;
  RESOURCE/OVEN(4), 2;
  RESOURCE/INSPECTOR(2), 3;
  GATE/CONVEYOR, OPEN, 4;

  CREATE, EXPON(3.0), 0.0, 1;
  PAINT AWAIT(1), BOOTH/1;
        ACTIVITY/1, UNFRM(4.0, 5.5), 1.0, RBOOTH;
  RBOOTH FREE, BOOTH/1;
  BAKE  AWAIT(2), OVEN/1;
        ACTIVITY/2, RNORM(10.0, 0.8), 1.0, ROVEN;
  ROVEN FREE, OVEN/1;
  INSP  AWAIT(3), INSPECTOR/1;
        ACTIVITY/3, UNFRM(2.0, 3.0), 1.0, RINSP;
  RINSP FREE, INSPECTOR/1;
        ACTIVITY/4, 0.5, 0.12, PAINT;
        ACTIVITY/5, 0.5, 0.88, SHIP;
  SHIP  COLCT, INT(1), BODY_LEAD_TIME;
        TERMINATE;

  OVHI  DETECT, SS(1), XP, 178.0, 0.1;
        ASSIGN, XX(1)=0.95;
        TERMINATE;
ENDNETWORK;
FIN;
